SET blocks = '[{"type":"text","content":"*The Fears* marked a significant milestone in my career—supporting Jo Winiarski''s scenic design for an Off Broadway production at Signature Theatre, one of New York''s most prestigious non-profit theatre companies. This dark comedy by Emma Sheanshang explores trauma, therapy, and the absurdity of modern wellness culture through the lens of a Buddhist-inspired group therapy session."},{"type":"header","content":"The Production"},{"type":"text","content":"Directed by Dan Algrant and presented by Academy Award-winning filmmaker Steven Soderbergh, *The Fears* premiered at Signature Theatre in 2023 to critical acclaim. The play follows five strangers who gather for a weekend retreat led by a charismatic facilitator, where therapeutic exercises spiral into increasingly surreal and darkly comic territory.\\n\\nJo Winiarski''s scenic design created an intimate therapy space—warm wood tones, comfortable seating, and Buddhist iconography—that gradually revealed its own theatrical artifice as the play''s reality bent and twisted. The design supported both the play''s comedic moments and its deeper exploration of collective trauma and the commodification of healing.\\n\\nThe New York Times praised the production''s ability to balance satire with genuine emotional resonance, noting how the creative team''s work elevated Sheanshang''s sharp dialogue and psychological insights."},{"type":"image","url":"https://files.manuscdn.com/user_upload_by_module/session_file/310519663337866878/AbGBGOStrbGvbTsE.jpg","caption":"The Fears at Signature Theatre, 2023. Scenic design by Jo Winiarski. The intimate therapy space setting with Buddhist iconography. Photo by Joan Marcus."},{"type":"header","content":"The Creative Team"},{"type":"team","title":"The Creative Team","members":[{"name":"Emma Sheanshang","role":"Playwright"},{"name":"Dan Algrant","role":"Director"},{"name":"Jo Winiarski","role":"Scenic Designer"},{"name":"Brandon P.T. Davis","role":"Assistant Scenic Designer"},{"name":"Jeff Croiter","role":"Lighting Designer"},{"name":"Jane Shaw","role":"Sound Designer"},{"name":"David Robinson","role":"Costume Designer"},{"name":"Steven Soderbergh","role":"Presented By"}]},{"type":"header","content":"Off Broadway Recognition"},{"type":"text","content":"Working on an Off Broadway production at Signature Theatre provided invaluable experience in New York''s professional theatre ecosystem. Signature Theatre, recipient of the 2005 Special Tony Award for Outstanding Regional Theatre, is known for championing new American plays and supporting playwrights throughout their careers. Contributing to a world premiere in this environment represented an important step in building regional and national recognition as a scenic design professional."},{"type":"header","content":"About Signature Theatre"},{"type":"text","content":"Signature Theatre Company is dedicated to honoring and extending the legacy of America''s master playwrights. Located in Manhattan''s Pershing Square Signature Center, the company produces seasons devoted to exploring the work of individual playwrights, alongside new works and revivals that celebrate the American theatrical canon."},{"type":"link","url":"https://www.signaturetheatre.org","label":"Visit Signature Theatre"}]'
WHERE slug = 'the-fears-signature-theatre-off-broadway';

